  scope.files.map(function(f) { return "  - " + f }).join("\\n") + "\\n\\n" +
  "## Stats\\n" + scope.stats + "\\n\\n" +
  (scope.conventions ? "## Conventions (CLAUDE.md)\\n" + scope.conventions + "\\n" : "") +
  "</context>\\n\\n"

